#pragma once

/**
 * @file CoverJpegs.h
 * @brief Embedded JPEG cover images for the ID3v2 APIC frames of synthesized MP3 files.
 */

#include <Arduino.h>

/**
 * @brief Real 320x320 baseline JPEG covers for ID3 APIC (generated by scripts/gen_covers.ps1).
 */
namespace CoverJpegs {

/** @brief One embedded JPEG image in flash. */
struct Cover {
    const uint8_t* data;  ///< JPEG bytes (starts with FF D8).
    uint32_t len;         ///< JPEG length in bytes.
};

static constexpr uint8_t kCount = 4;
extern const Cover kCovers[kCount];

/**
 * @brief Look up an embedded cover by its 1-based number.
 *
 * @param cover  Cover number 1..kCount (0 = placeholder in MediaLayout::Node::cover).
 * @return Pointer to the JPEG for cover 1..kCount, else nullptr.
 */
inline const Cover* get(uint8_t cover) {
    return (cover >= 1 && cover <= kCount) ? &kCovers[cover - 1] : nullptr;
}

/**
 * @brief Return the APIC slot size that fits every cover, so a live cover swap never changes the file size.
 *
 * @return Largest cover length rounded up to a multiple of 512 bytes.
 */
inline uint32_t slotBytes() {
    uint32_t m = 0;
    for (uint8_t i = 0; i < kCount; i++) m = kCovers[i].len > m ? kCovers[i].len : m;
    return (m + 511u) & ~511u;
}

}  // namespace CoverJpegs
